#!/usr/bin/env python3
import csv, json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
with (root / 'output/rewrite-master-enriched.csv').open(newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))
data = json.dumps(rows, ensure_ascii=False).replace('</', '<\\/')
html = '''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CVR review worksheet</title><style>
body{margin:0;background:#f7f6f1;color:#536264;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1600px;margin:auto;padding:28px 32px}h1{color:#17343a;font-size:42px;letter-spacing:-.05em;margin:8px 0}.eyebrow,small{color:#9a7b4f;font:11px monospace;text-transform:uppercase;letter-spacing:.1em}.intro{max-width:800px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0 12px}.filters input,.filters select{padding:11px;border:1px solid #d6dfdc;background:white;color:#17343a}.filters input{min-width:280px;flex:1}.table{overflow:auto;background:white;border:1px solid #d6dfdc}table{border-collapse:collapse;width:100%;min-width:1400px}th{background:#0e252a;color:white;padding:12px;text-align:left;font:11px monospace;text-transform:uppercase}td{padding:14px 12px;border-bottom:1px solid #e5ebe8;vertical-align:top}.title{font-weight:800;color:#17343a;max-width:300px}.meta{font:11px monospace;color:#315c63}.pill{display:inline-block;padding:4px 8px;border-radius:20px;background:#eee5d6;color:#765b35;font:10px monospace;text-transform:uppercase}.ready{background:#e2efe7;color:#4b765e}.blocked{background:#f6e3df;color:#a44b3e}details{max-width:480px}summary{cursor:pointer;color:#315c63;font-weight:700}.source{display:inline-block;margin-top:7px;color:#315c63}.price{color:#765b35;font-weight:800}@media(max-width:800px){.wrap{padding:20px 14px}h1{font-size:32px}}
</style><main class="wrap"><div class="eyebrow">Manual source review / 50 listings</div><h1>Decide each property, one row at a time.</h1><p class="intro">Mở source page, đọc phần Evidence, rồi tự xác nhận building/project, type, features và size. Đây là worksheet để quyết định dữ liệu, chưa phải công cụ đồng bộ.</p><div class="filters"><input id="q" placeholder="Tìm title, building, source key…"><select id="s"><option value="">Tất cả trạng thái</option></select><select id="t"><option value="">Tất cả loại</option></select><select id="c"><option value="">Tất cả thành phố</option></select></div><div class="table"><table><thead><tr><th>Listing & nguồn</th><th>Evidence nguồn để đọc</th><th>Mapping hiện tại</th><th>Facts & giá</th><th>QA</th></tr></thead><tbody id="b"></tbody></table></div><p id="count"></p></main><script>const D=__DATA__,e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cl=s=>s.includes('invalid')||s.includes('source_review')?'blocked':s==='ready_for_review'?'ready':'',lab=s=>String(s||'').replaceAll('_',' ');function add(id,k){[...new Set(D.map(r=>r[k]).filter(Boolean))].sort().forEach(v=>document.querySelector(id).insertAdjacentHTML('beforeend',`<option value="${e(v)}">${e(v)}</option>`))}function draw(){let q=document.querySelector('#q').value.toLowerCase(),s=document.querySelector('#s').value,t=document.querySelector('#t').value,c=document.querySelector('#c').value;let a=D.filter(r=>(!s||r.content_status===s)&&(!t||r.property_type===t)&&(!c||r.property_city===c)&&(r.original_title+' '+r.rewritten_title+' '+r.building_name+' '+r.source_key).toLowerCase().includes(q));document.querySelector('#b').innerHTML=a.map(r=>`<tr><td><div class="title">${e(r.rewritten_title||r.original_title)}</div><a class="source" href="${e(r.source_url_internal)}" target="_blank" rel="noreferrer">Mở trang nguồn ↗</a><div class="meta">${e(r.source_key)} · HTTP ${e(r.source_http_status)}</div><details><summary>Title gốc</summary>${e(r.original_title)}</details></td><td><details open><summary>Đọc mô tả nguồn (${e(r.source_description_word_count)} words)</summary><p>${e(r.source_description||'Không có mô tả')}</p></details><div class="meta">Dùng evidence này để xác nhận thông tin.</div></td><td><b>${e(r.building_name||'Chưa xác định')}</b><div class="meta">confidence: ${e(r.project_confidence||'unknown')}<br>type: ${e(r.property_type||'—')} · city: ${e(r.property_city||'—')}<br>features: ${e(r.property_features||'Chưa xác định')}</div></td><td>${e(r.bedrooms||'—')} bd · ${e(r.bathrooms||'—')} ba<br>Size: ${e(r.size||'—')} sqm<br><span class="price">${e(r.public_price||'—')} ${e(r.price_currency||'')}</span><div class="meta">source ${e(r.source_price||'—')} · −${e(r.discount_percent||'8')}%</div></td><td><span class="pill ${cl(r.content_status)}">${e(lab(r.content_status))}</span><div class="meta">${e(r.qa_notes||'')}</div></td></tr>`).join('');document.querySelector('#count').textContent=`Hiển thị ${a.length}/${D.length} listing`}add('#s','content_status');add('#t','property_type');add('#c','property_city');draw();['q','s','t','c'].forEach(id=>document.querySelector('#'+id).addEventListener('input',draw))</script>'''
(root / 'output/cvr-apartments-dashboard.html').write_text(html.replace('__DATA__', data).replace('Chưa xác định', 'Không thuộc tòa nhà/project'), encoding='utf-8')
print('Wrote manual review dashboard with', len(rows), 'listings')
